            margin: 1in auto;
            max-width: 8.5in;
            padding: 0.5in;
            background: #fff;
            color: #000;
        }

        .column {
            column-count: 2;
            column-gap: 1.2in;
        }

        .column p {
            margin-bottom: 0.8em;
        }

        .left-col, .right-col {
            display: inline-block;
            vertical-align: top;
            width: 48%;
        }

        .header {
            text-align: center;
            font-family: 'Georgia', serif;
            font-size: 18pt;
            font-weight: 600;
            margin-bottom: 0.3in;
        }

        .subheader {
            text-align: center;
            font-size: 14pt;
            margin-bottom: 0.5in;
        }

        .placeholder {
            background: #f0f0f0;
            border: 1px dashed #333;
            width: 100%;
            height: 180px;
            margin: 0.5in 0;
            display: flex;
            align-items: center;
            justify-content: center;
            font-style: italic;
            color: #555;
            text-align: center;
        }

        table {
            width: 100%;
            border-collapse: collapse;
            margin: 0.5in 0;
        }

        td {
            border: 1px solid #000;
            padding: 4px;
        }

        .signature {
            width: 2.5in;
            height: 0.8in;
            border-bottom: 1px solid #000;
            display: inline-block;
            margin-top: 0.2in;
        }
